import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"A/B 槽位、安装与 OTA 更新","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/update-ota.md","filePath":"zh/manual/update-ota.md"}'),s={name:"zh/manual/update-ota.md"};function c(p,e,n,i,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="a-b-槽位、安装与-ota-更新" tabindex="-1">A/B 槽位、安装与 OTA 更新 <a class="header-anchor" href="#a-b-槽位、安装与-ota-更新" aria-label="Permalink to &quot;A/B 槽位、安装与 OTA 更新&quot;">​</a></h1><h2 id="更新向导" tabindex="-1">更新向导 <a class="header-anchor" href="#更新向导" aria-label="Permalink to &quot;更新向导&quot;">​</a></h2><p>预期路径是向导——它用五个受检步骤走完&quot;把本机带到最新版本&quot;这一意图：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>能修复什么</th></tr></thead><tbody><tr><td>1/5 网络</td><td>读取 IP 状态</td><td>地址为 0.0.0.0 时提供 DHCP 修复，然后复查</td></tr><tr><td>2/5 A/B 盘</td><td>读取 <code>update status</code></td><td>盘缺失时：显示 <code>lsblk</code>，引导你完成双重确认的 <code>abdisk &lt;dev&gt;</code>，然后复查</td></tr><tr><td>3/5 DNS</td><td>对从实时 <code>config get update_url</code> 取值解析出的更新主机做域名解析</td><td>-</td></tr><tr><td>4/5 检查</td><td><code>checkupdate</code></td><td>已是最新则以 OK 结束向导</td></tr><tr><td>5/5 安装</td><td>经确认的在线更新</td><td>经确认重启进入新槽位</td></tr></tbody></table><p>每一步都会打印判定（<code>[OK]</code> / <code>[!!]</code>），前提条件无法修复时干净中止——没有单独的 <code>y</code>，任何破坏性操作都不会运行。</p><h2 id="a-b-机制" tabindex="-1">A/B 机制 <a class="header-anchor" href="#a-b-机制" aria-label="Permalink to &quot;A/B 机制&quot;">​</a></h2><p>selfhost 服务维护两个槽位（A 与 B）外加一个启动标志：</p><ul><li>GRUB 读取标志并引导活动槽位；菜单提供强制槽位项作为手动覆盖。</li><li>更新安装到<em>非活动</em>槽位，期间系统照常运行。</li><li>下次启动切换到更新后的槽位；如果你不认可它，<code>update rollback</code> 会切回去。</li></ul><p><code>update status</code> 展示全貌：当前版本、当前启动槽位、下次启动、可用更新、在线更新标志，以及 A/B 盘是否存在。</p><h2 id="安装到磁盘" tabindex="-1">安装到磁盘 <a class="header-anchor" href="#安装到磁盘" aria-label="Permalink to &quot;安装到磁盘&quot;">​</a></h2><p>从运行中的 ISO 引导系统出发：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dskstat                (pick a target disk, e.g. hd0)</span></span>
<span class="line"><span>ush&gt; install hd0            (partition + copy the running kernel +</span></span>
<span class="line"><span>                             GRUB boot files + /etc volume)</span></span></code></pre></div><p>或者走向导：<code>disk-tool</code> -&gt; A/B 更新盘管理器 -&gt; 创建（会询问设备名，重输并确认）。</p><p><code>install</code> 把 multiboot2 模块 <code>self</code>——也就是此刻正在运行的那个内核 ELF——复制到磁盘，因此已安装的系统始终与其安装程序匹配。<code>abdisk &lt;dev&gt;</code> 做同样的事，只是做成 A/B 更新盘的形态（双槽位 + 标志；会销毁数据）。<code>abcfg</code> 显示这些命令写出的确切 grub.cfg 文件。</p><h2 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; checkupdate            (reads the update URL from /etc/opencube.conf</span></span>
<span class="line"><span>                             - http or https - and parses the manifest)</span></span>
<span class="line"><span>ush&gt; config get update_url  (the configuration key it uses)</span></span></code></pre></div><p>清单就是网站上的 <code>update.json</code>：版本、构建号、包 URL、包 SHA256、大小。构建号比较是数值式的（BUG-0347），因此即使版本字符串相同，构建号更高的重构建也会胜出。</p><h2 id="更新源与镜像" tabindex="-1">更新源与镜像 <a class="header-anchor" href="#更新源与镜像" aria-label="Permalink to &quot;更新源与镜像&quot;">​</a></h2><p>更新源就是 <code>update_url</code> 配置键——一个指向 <code>update.json</code> 清单的普通 HTTPS URL。向导第 3 步读取实时值（<code>config get update_url</code>）并在任何网络动作之前先解析它的主机名。要让机器指向另一个源，用普通的配置写入器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; config set update_url &lt;url&gt;</span></span></code></pre></div><p>已知可用值（它们都从 gh-pages 分支提供<em>同一份</em>清单，选你网络里最快的一个即可）：</p><table tabindex="0"><thead><tr><th>源</th><th>URL</th></tr></thead><tbody><tr><td>官方（GitHub Pages）</td><td><code>https://cubestudio-dev.github.io/OpenCubeOS/update.json</code></td></tr><tr><td>GitHub raw 镜像</td><td><code>https://raw.githubusercontent.com/cubestudio-dev/OpenCubeOS/gh-pages/update.json</code></td></tr><tr><td>jsDelivr CDN 镜像</td><td><code>https://cdn.jsdelivr.net/gh/cubestudio-dev/OpenCubeOS@gh-pages/update.json</code></td></tr></tbody></table><p>自定义值也可用——必须以 <code>http://</code> 或 <code>https://</code> 开头，并指向同样形状的清单（否则 <code>checkupdate</code> 会打印解析错误）。镜像在你某个主机被屏蔽或很慢时有用：清单携带绝对包 URL，所以切换源后，包下载跟随清单自身的 <code>url</code> 字段。</p><h2 id="应用更新" tabindex="-1">应用更新 <a class="header-anchor" href="#应用更新" aria-label="Permalink to &quot;应用更新&quot;">​</a></h2><p>在线流程（向导第 5 步确认后所运行的，也是裸 <code>update direct</code> 所做的）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update direct          check -&gt; download -&gt; verify -&gt; install</span></span>
<span class="line"><span>ush&gt; reboot                 boot the updated slot</span></span></code></pre></div><p>离线/物理隔离的机器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update --local /path/to/package.tar.gz</span></span></code></pre></div><p>OTA 包（<code>opencube-&lt;version&gt;-update.tar.gz</code>）携带新的内核 ELF 和一份清单。校验是密码学层面的：清单 SHA256 在安装过程中强制校验——未通过的包会被拒绝。</p><p>大包从不压迫内存：下载器以 4 KiB 块流式写盘（<code>DL_CHUNK</code>，<code>ocos/services/selfhost/src/svc_selfhost_ab.c</code> 的 <code>ota_update_download</code>），因此包远大于内存也能完成更新；内存里只会有 SHA256 状态和一个块缓冲区。</p><h2 id="回滚" tabindex="-1">回滚 <a class="header-anchor" href="#回滚" aria-label="Permalink to &quot;回滚&quot;">​</a></h2><p>切换后如果某个槽位表现异常：</p><ol><li>在 GRUB 菜单中选择另一个槽位（强制项），或者</li><li>在运行中的系统里执行 <code>ush&gt; update rollback</code>。</li></ol><p><code>ab_partition_test</code> 在一块临时盘上演练槽位发现、标志与槽位切换，不会碰你真实的启动盘。</p><h2 id="更新相关命令" tabindex="-1">更新相关命令 <a class="header-anchor" href="#更新相关命令" aria-label="Permalink to &quot;更新相关命令&quot;">​</a></h2><p><code>checkupdate</code>、<code>update</code>（向导 + 上面的链）、<code>rollback</code>、<code>config</code>（更新 URL 相关键）、<code>abdisk</code>、<code>abcfg</code>、<code>ab_partition_test</code>。它们同时也是 <code>update</code> / <code>disk-tool</code> 应用的经典操作。完整列表（每条命令一页）见<a href="./commands/">命令索引</a>——&quot;OTA 更新与 A/B 槽位&quot;领域。</p><h2 id="内部机制" tabindex="-1">内部机制 <a class="header-anchor" href="#内部机制" aria-label="Permalink to &quot;内部机制&quot;">​</a></h2><p>关于标志如何存储、install 如何向非活动槽位分阶段写入，以及与 GRUB 的启动标志握手，见 <a href="./../internals/ota-ab.html">../internals/ota-ab.md</a>。</p>`,39)])])}const b=t(s,[["render",c]]);export{u as __pageData,b as default};
